package com.hms.patients;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/patient-identifiers") public class PatientIdentifierSettingsController {private final TenantRepository tenants;private final PatientIdentifierSettingsRepository settings;public PatientIdentifierSettingsController(TenantRepository t,PatientIdentifierSettingsRepository s){tenants=t;settings=s;} @GetMapping public PatientIdentifierSettings get(@PathVariable String tenantSlug){return settings.findByTenantId(tenant(tenantSlug)).orElseThrow(()->new IllegalArgumentException("Patient identifier settings not configured"));} @PutMapping public PatientIdentifierSettings update(@PathVariable String tenantSlug,@Valid @RequestBody UpdatePatientIdentifierSettingsRequest r){if(r.abhaRequired()&&!r.abhaEnabled())throw new IllegalArgumentException("ABHA cannot be required when disabled");UUID t=tenant(tenantSlug);PatientIdentifierSettings s=settings.findByTenantId(t).orElseGet(()->new PatientIdentifierSettings(t,r));s.apply(r);return settings.save(s);} private UUID tenant(String s){return tenants.findBySlug(s).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(s));}}
